param([Parameter(Mandatory)][string]$Executable,[Parameter(Mandatory)][string]$ProviderExecutable,[Parameter(Mandatory)][string]$ProjectRoot,[Parameter(Mandatory)][string]$ScratchRoot)
. (Join-Path $PSScriptRoot 'ProjectedRequest.ps1')
$ErrorActionPreference='Stop';$checks=0;$service=$null;$provider=$null
$root=Join-Path $ScratchRoot ('continuity-'+[Guid]::NewGuid().ToString('N'));New-Item -ItemType Directory -Path $root -Force|Out-Null
$env:TEMP=$root;$env:TMP=$root;$env:HIBERNATION_SESSION_KEY='continuity-session-fixture';$env:HIBERNATION_CONTINUITY_KEY='continuity-model-fixture'
$headers=@{Authorization='Bearer '+$env:HIBERNATION_SESSION_KEY};$readyPath=Join-Path $root 'ready.json';$configPath=Join-Path $root 'config.json';$providerRoot=Join-Path $root 'provider';New-Item -ItemType Directory -Path $providerRoot|Out-Null
function Check([bool]$Value,[string]$Name){if(!$Value){throw "CONTINUITY FAILED: $Name"};$script:checks++;Write-Output "PASS $Name"}
function Wait-For([scriptblock]$Probe,[string]$Name,[int]$Seconds=25){$end=[DateTime]::UtcNow.AddSeconds($Seconds);while([DateTime]::UtcNow-lt$end){if(& $Probe){return};Start-Sleep -Milliseconds 80};throw "CONTINUITY TIMEOUT: $Name"}
function Api([string]$Path,$Data=$null){$a=@{Uri=($script:origin+$Path);Headers=$headers;TimeoutSec=12};if($null-ne$Data){$a.Method='Post';$a.ContentType='application/json; charset=utf-8';$a.Body=[Text.Encoding]::UTF8.GetBytes(($Data|ConvertTo-Json -Depth 50 -Compress))};Invoke-RestMethod @a}
function Start-Backend{$script:service=Start-Process -FilePath $Executable -ArgumentList ('--config "'+$configPath+'" --ready-file "'+$readyPath+'"') -WindowStyle Hidden -PassThru -RedirectStandardOutput (Join-Path $root 'service.log') -RedirectStandardError (Join-Path $root 'error.log');Wait-For {if($script:service.HasExited){throw 'service exited'};if(Test-Path $readyPath){try{return (Get-Content $readyPath -Raw|ConvertFrom-Json).pid-eq$script:service.Id}catch{}};return $false} 'backend ready';$script:origin='http://127.0.0.1:'+((Get-Content $readyPath -Raw|ConvertFrom-Json).port)}
function Stop-Backend{$null=Api '/api/shutdown' @{};$script:service.WaitForExit(15000)|Out-Null;Check $script:service.HasExited 'graceful restart preserves continuity'}
function Idle{Wait-For {!(Api '/api/chat').busy} 'idle'}
function Plan($Items){@{nonce=[Guid]::NewGuid().ToString('N');responses=@($Items|ForEach-Object {@{response=$_}})}|ConvertTo-Json -Depth 50|Set-Content (Join-Path $providerRoot 'plan.json') -Encoding utf8}
function Tool([string]$Id,[string]$Name,$Arguments){@{id=$Id;tool=$Name;args=$Arguments}}
function Calls($Items){@{version=1;kind='call';text=$null;calls=@($Items)}}
function Reply([string]$Text){@{version=1;kind='reply';text=$Text;calls=@();presentation=@{speech=$false;bubble=$false}}}
function Silence{@{version=1;kind='silence';text=$null;calls=@()}}
function Message([string]$Text){$result=Api '/api/message' @{request_id=[Guid]::NewGuid().ToString('N');text=$Text};Idle;return $result}
function Capture{Get-Content (Join-Path $providerRoot 'last-request.json') -Raw|ConvertFrom-Json -Depth 60}
function Feedback{$capture=Capture;@(($capture.messages[-1].content|ConvertFrom-Json -Depth 50).tool_results)}
try{
 $provider=Start-Process -FilePath $ProviderExecutable -ArgumentList ('"'+$providerRoot+'"') -WindowStyle Hidden -PassThru -RedirectStandardOutput (Join-Path $root 'provider.log') -RedirectStandardError (Join-Path $root 'provider-error.log');Wait-For {Test-Path (Join-Path $providerRoot 'port')} 'provider ready';$fixture='http://127.0.0.1:'+([int](Get-Content (Join-Path $providerRoot 'port')))
 $character=Join-Path $root 'synthetic-character';New-Item -ItemType Directory -Path $character|Out-Null
 @{schemaVersion=1;version=1;id='continuity-synthetic-fixture';displayName='合成角色 C';notice='完全合成的连续性回归检查。';identity='只存在于隔离测试中的虚构角色。';attention=@('合成问题');boundaries=@('依据实际回执推进自己的问题。可以说不，也可以暂时安静。');character=@{identity='只存在于隔离测试中的虚构角色。';voice='自然交谈。';autonomy=@('可以说不，也可以暂时安静。');boundaries=@('依据实际回执推进自己的问题。')}}|ConvertTo-Json -Depth 10|Set-Content -LiteralPath (Join-Path $character persona.json) -Encoding utf8
 @{schemaVersion=1;version=1;initial='initial';stages=@(@{id='initial';name='合成初始';description='隔离连续性检查。';next='';minimumEvidence=0});reviewPolicy='不改变阶段。'}|ConvertTo-Json -Depth 10|Set-Content -LiteralPath (Join-Path $character stages.json) -Encoding utf8
 $config=Get-Content (Join-Path $ProjectRoot 'config/example.json') -Raw|ConvertFrom-Json -AsHashtable;$config.dataRoot=Join-Path $root 'data';$config.characterRoot=$character;$config.uiRoot=Join-Path $ProjectRoot 'ui';$config.plugins=@{};$config.maxStartsPerHour=1000;$config.recentMessageCount=2;$config.maxMemoriesInContext=1;$config.solitudeIntervalMs=600000;$config.idleBeforeSolitudeMs=0
 $config.computer=@{enabled=$false;readRoots=@()};$config.skills=@{enabled=$false;useBuiltins=$false;root=(Join-Path $root 'skills');grants=@()}
 foreach($id in @('fixture-a','fixture-b','reviewer')){$config.profiles+=@{id=$id;label=$id;enabled=$true;protocol='chat-completions';origin=$fixture;basePath='/v1';model=if($id-eq'reviewer'){'fixture-reviewer'}else{$id};credentialEnvironment='HIBERNATION_CONTINUITY_KEY';timeoutMs=10000;maxOutputTokens=2048;supportsJsonSchema=$false}}
 $config|ConvertTo-Json -Depth 40|Set-Content $configPath -Encoding utf8;Start-Backend;$null=Api '/api/model' @{id='fixture-a'}
 Plan @((Calls @((Tool 'remember' 'memory.remember' @{kind='conversation';text='钟塔为什么停在三点，还没有解释。';source_ids=@('${event_id}')}),(Tool 'rest' 'state.propose' @{activity='withdrawing';intensity=-0.7;valence=-0.4;focus='钟塔上没有走动的指针';source_id='${event_id}'}))),(Calls @((Tool 'question' 'reflection.open' @{id='clock';question='钟塔为什么停在三点？';source_ids=@('${last_memory_id}')}))),(Calls @((Tool 'later' 'schedule.create' @{id='clock';topic='重新看看钟塔停在三点的可能性';source_ids=@('${last_memory_id}');after_ms=60000}))),(Reply '这件事我想留一会儿。'))
 $null=Message '钟塔为什么停在三点？';$scheduled=(Feedback)[0];Check $scheduled.ok 'role schedules its own question';$memory=(Api '/api/memories').memories[0];$memoryId=$memory.id;$initial=(Api '/api/chat').messages.Count
 Check ((Api '/api/state').jobs.Where({$_.id-eq'routine.clock'}).Count-eq1) 'question creates exactly one persistent job'
 $capture=Capture;Check ($capture.messages[0].content.Contains('可以说不')-and!$capture.messages[0].content.Contains('实验代称；运行结果')) 'role receives expression and autonomy rules without administrative persona notes'
 Stop-Backend;Start-Backend;$null=Api '/api/model' @{id='fixture-b'}
 Plan @((Calls @((Tool 'questions' 'reflection.list' @{}),(Tool 'state' 'state.observe' @{}))),(Reply '先让我安静一会儿。'));$null=Message '换个连接之后，你还想继续说吗？';$feedback=Feedback
 Check ($feedback[0].result.questions[0].id-eq'clock') 'unresolved question survives process and model switch';Check ($feedback[1].result.version-eq4-and$feedback[1].result.focus-eq'钟塔上没有走动的指针'-and$feedback[1].result.desired_activity-eq'withdrawing') 'model switch preserves self-directed activity and focus';Check ($feedback[1].result.willingness-ge0-and$feedback[1].result.willingness-le1) 'independent willingness remains bounded'
 Check ($feedback[1].result.affect.emotions.PSObject.Properties.Name.Count-eq7-and$feedback[1].result.affect.desires.PSObject.Properties.Name.Count-eq6) 'current state also preserves the complete bounded affect view'
 Plan @((Calls @((Tool 'chime' 'memory.remember' @{kind='conversation';text='海蓝色的风铃挂在厨房窗前，雨停时会响。';source_ids=@('${event_id}')}))),(Reply '听见了。'));$null=Message '厨房窗前的海蓝色风铃';$chimeId=(Feedback)[0].result.id
 for($i=0;$i-lt5;$i++){Plan @((Calls @((Tool 'unrelated' 'memory.remember' @{kind='conversation';text=('桌上的杯子编号'+$i);source_ids=@('${event_id}')}))),(Reply '嗯。'));$null=Message ('杯子编号'+$i)}
 Plan @((Reply '厨房窗前那只。'));$null=Message '海蓝色风铃挂在哪儿？';$retrieved=Model-CurrentEvent (Capture);Check (@($retrieved.authorized_context|Where-Object id -eq $chimeId).Count-eq1) 'topic retrieval finds an older memory without pinning an unrelated question'
 Plan @((Reply '那个问题还留着。'));$null=Message '钟塔三点的问题还在吗？';$capture=Capture;$context=Model-CurrentEvent $capture
 Check (@($context.authorized_context|Where-Object id -eq $memoryId).Count-eq1) 'older relevant memory beats newer unrelated memories under one-memory budget';Check (!$context.time_context.offline_experiences_inferred-and$context.time_context.resumed_at_ms-gt0) 'time gap is explicit without fabricated offline activity'
 $utcClock=[DateTimeOffset]$context.time_context.utc_time
 Check ($context.time_context.formatted_time_available-and[Math]::Abs($utcClock.ToUnixTimeMilliseconds()-$context.time_context.now_ms)-lt1000-and$context.time_context.host_local_time-and$context.time_context.clock_source-eq'host_os') 'model receives readable UTC and host-local time from the authoritative clock'
 $beforeAlone=(Api '/api/chat').messages.Count
