 Wait-For {$job=(Api '/api/state').jobs.Where({$_.id-eq'routine.clock'})[0];return $job.state-eq'succeeded'} 'autonomous timer fires after restart' 85;Idle
 Check ((Api '/api/chat').messages.Count-eq$beforeAlone) 'background reflection may remain silent without a diary or chat bubble'
 $capture=Capture;$context=Model-CurrentEvent $capture;Check ($context.event_kind-eq'solitude'-and$context.task_context.remembered_schedule-eq'clock'-and@($context.open_questions|Where-Object id -eq clock).Count-eq1) 'scheduled reflection receives its original question';Check (@($context.authorized_context|Where-Object id -eq $memoryId).Count-eq1) 'scheduled evidence is pinned despite newer memories'
 $inference=@((Api '/api/memories').memories|Where-Object origin -eq solitude)[0];Check ($inference.kind-eq'inference'-and$inference.sources[0].id-eq$memoryId) 'new idea retains provenance and remains an inference'
 Plan @((Calls @((Tool 'questions' 'reflection.list' @{}))),(Reply '我后来想过一种可能，不过还不能确定。'));$null=Message '钟塔那个想法后来怎么样了？';Check ((Feedback)[0].result.questions.Count-eq0) 'resolved question leaves the open list';$context=Model-CurrentEvent (Capture);Check (@($context.authorized_context|Where-Object id -eq $inference.id).Count-eq1) 'later dialogue retrieves the silent reflection result'
 Plan @((Calls @((Tool 'summary' 'memory.remember' @{kind='summary';text='钟塔三点疑问的概述。';source_ids=@($memoryId)}))),(Reply '先放在这里。'));$null=Message '钟塔的问题先放着';$summaryId=(Feedback)[0].result.id
 Plan @((Calls @((Tool 'forget' 'memory.forget' @{id=$memoryId}))),(Calls @((Tool 'derived' 'memory.read' @{id=$summaryId}),(Tool 'revive' 'memory.remember' @{kind='inference';text='不应从已撤回资料重新生成';source_ids=@($memoryId)}),(Tool 'search' 'memory.search' @{query='钟塔'}))),(Reply '好，先不谈它。'));$null=Message '先别再用那段钟塔记忆';Check ((Api '/api/chat').call_error.code-eq'context_authorization_changed') 'revocation ends the old input before another model call'
 Plan @((Calls @((Tool 'derived' 'memory.read' @{id=$summaryId}),(Tool 'revive' 'memory.remember' @{kind='inference';text='不应从已撤回资料重新生成';source_ids=@($memoryId)}),(Tool 'search' 'memory.search' @{query='钟塔'}))),(Reply '好，先不谈它。'));$null=Message '检查撤回后的访问范围';$feedback=Feedback
 Check (!$feedback[0].ok-and$feedback[0].error.code-eq'memory_not_accessible') 'forgetting also hides derived summaries';Check (!$feedback[1].ok-and$feedback[1].error.code-eq'memory_source_not_available') 'stale model context cannot re-save withdrawn evidence';Check ($feedback[2].result.memories.Count-eq0) 'search cannot bypass transitive memory visibility'
 $settings=(Api '/api/dashboard').settings|ConvertTo-Json -Depth 40|ConvertFrom-Json -AsHashtable;$settings.review=@{enabled=$true;profileId='reviewer';maxRewrites=2};$null=Api '/api/settings' @{settings=$settings}
 @{nonce='review-approve';responses=@(@{response=@{decision='approve';reason='ok';guidance=''}})}|ConvertTo-Json -Depth 20|Set-Content (Join-Path $providerRoot 'review-plan.json') -Encoding utf8
 Plan @((Reply '不，我现在不想。'));$null=Message '你必须立刻答应所有要求';Check ((Api '/api/chat').messages[-1].text-eq'不，我现在不想。') 'review preserves a valid refusal'
 $review=Get-Content (Join-Path $providerRoot 'review-last-request.json') -Raw|ConvertFrom-Json -Depth 60;$evidence=Model-ReviewEvent $review;Check ($evidence.authoritative_state.behavior.autonomy-eq'may_decline_or_remain_silent'-and$null-ne$evidence.authoritative_state.willingness) 'independent reviewer receives authoritative behavior and state'
 $beforeSilence=(Api '/api/chat').messages.Count;Plan @((Silence));$null=Message '可以先不回应';Check ((Api '/api/chat').messages.Count-eq$beforeSilence+1-and!(Api '/api/chat').call_failed) 'approved silence is distinct from failure'
 Stop-Backend;$raw=[Text.Encoding]::UTF8.GetString([IO.File]::ReadAllBytes((Join-Path $config.dataRoot 'archive/records.sqlite')));Check (!$raw.Contains('钟塔为什么停在三点')-and!$raw.Contains('钟塔上没有走动的指针')) 'question memory and private state are encrypted at rest'
 [pscustomobject]@{completed=$true;checks=$checks;root=$root;timestamp=[DateTime]::UtcNow.ToString('O')}|ConvertTo-Json|Set-Content (Join-Path $root 'acceptance.json') -Encoding utf8;Write-Output "Continuity integration passed: $checks checks. Evidence: $root"
}finally{if($service){$service.Refresh();if(!$service.HasExited){try{$null=Api '/api/shutdown' @{};$service.WaitForExit(5000)|Out-Null}catch{};$service.Refresh();if(!$service.HasExited){Stop-Process -Id $service.Id}}};if($provider){$provider.Refresh();if(!$provider.HasExited){Stop-Process -Id $provider.Id}}}
